SELECT DATE_TRUNC('YEAR', order_date) AS year_start, SORT_ARRAY(COLLECT_SET(status)) AS status_list, APPROX_PERCENTILE(shipping_fee, 0.9) AS shipping_fee_p90, APPROX_PERCENTILE(discount, ARRAY(0.25, 0.5, 0.75)) AS discount_quartiles, ROUND(SUM(discount) / NULLIF(COUNT(CASE WHEN channel = 'store' THEN 1 END), 0), 2) AS discount_per_store, COUNT_IF(status = 'CANCELLED') AS cancelled_events FROM orders GROUP BY DATE_TRUNC('YEAR', order_date) ORDER BY shipping_fee_p90 DESC NULLS FIRST;
